import pandas as pd
import xgboost as xgb
import mlflow
import joblib

from pathlib import Path
from sklearn.compose import make_column_transformer
from sklearn.pipeline import make_pipeline
from sklearn.model_selection import GridSearchCV
from sklearn.metrics import classification_report
from sklearn.preprocessing import OneHotEncoder, StandardScaler


# Configure MLflow for GitHub Actions
mlflow.set_tracking_uri("file:./mlruns")

# Create or reuse the experiment by name
mlflow.set_experiment("tourism_package_prediction")

# Load datasets generated by the previous job
Xtrain = pd.read_csv("Xtrain.csv")
Xtest = pd.read_csv("Xtest.csv")
ytrain = pd.read_csv("ytrain.csv").squeeze()
ytest = pd.read_csv("ytest.csv").squeeze()

# Numerical features
numeric_features = [
    "Age",
    "CityTier",
    "DurationOfPitch",
    "NumberOfPersonVisiting",
    "NumberOfFollowups",
    "PreferredPropertyStar",
    "NumberOfTrips",
    "Passport",
    "PitchSatisfactionScore",
    "OwnCar",
    "NumberOfChildrenVisiting",
    "MonthlyIncome"
]

# Categorical features
categorical_features = [
    "TypeofContact",
    "Occupation",
    "Gender",
    "ProductPitched",
    "MaritalStatus",
    "Designation"
]

# Handle class imbalance
class_weight = (
    ytrain.value_counts()[0] /
    ytrain.value_counts()[1]
)

# Preprocessing pipeline
preprocessor = make_column_transformer(
    (StandardScaler(), numeric_features),
    (
        OneHotEncoder(handle_unknown="ignore"),
        categorical_features
    )
)

# XGBoost classifier
xgb_model = xgb.XGBClassifier(
    scale_pos_weight=class_weight,
    random_state=42,
    n_jobs=1,
    eval_metric="logloss"
)

# Hyperparameter grid
param_grid = {
    "xgbclassifier__n_estimators": [100, 200],
    "xgbclassifier__max_depth": [3, 5],
    "xgbclassifier__colsample_bytree": [0.8, 1.0],
    "xgbclassifier__colsample_bylevel": [0.8, 1.0],
    "xgbclassifier__learning_rate": [0.05, 0.1],
    "xgbclassifier__reg_lambda": [1, 5]
}

# Correct model pipeline
model_pipeline = make_pipeline(
    preprocessor,
    xgb_model
)

# Start MLflow run
with mlflow.start_run():

    # Hyperparameter tuning
    grid_search = GridSearchCV(
        model_pipeline,
        param_grid,
        cv=5,
        n_jobs=-1,
        scoring="f1"
    )

    grid_search.fit(Xtrain, ytrain)

    # Log each parameter combination
    results = grid_search.cv_results_

    for i in range(len(results["params"])):
        with mlflow.start_run(nested=True):
            mlflow.log_params(results["params"][i])
            mlflow.log_metric(
                "mean_test_score",
                results["mean_test_score"][i]
            )
            mlflow.log_metric(
                "std_test_score",
                results["std_test_score"][i]
            )

    # Best parameters
    mlflow.log_params(grid_search.best_params_)

    best_model = grid_search.best_estimator_

    # Classification threshold
    classification_threshold = 0.5

    mlflow.log_param(
        "classification_threshold",
        classification_threshold
    )

    # Training predictions
    y_pred_train_proba = best_model.predict_proba(
        Xtrain
    )[:, 1]

    y_pred_train = (
        y_pred_train_proba >= classification_threshold
    ).astype(int)

    # Test predictions
    y_pred_test_proba = best_model.predict_proba(
        Xtest
    )[:, 1]

    y_pred_test = (
        y_pred_test_proba >= classification_threshold
    ).astype(int)

    # Evaluate
    train_report = classification_report(
        ytrain,
        y_pred_train,
        output_dict=True,
        zero_division=0
    )

    test_report = classification_report(
        ytest,
        y_pred_test,
        output_dict=True,
        zero_division=0
    )

    # Log metrics
    mlflow.log_metrics({
        "train_accuracy": train_report["accuracy"],
        "train_precision": train_report["1"]["precision"],
        "train_recall": train_report["1"]["recall"],
        "train_f1-score": train_report["1"]["f1-score"],
        "test_accuracy": test_report["accuracy"],
        "test_precision": test_report["1"]["precision"],
        "test_recall": test_report["1"]["recall"],
        "test_f1-score": test_report["1"]["f1-score"]
    })

    # Save model in deployment directory
    project_root = Path(__file__).resolve().parents[1]

    model_path = (
        project_root / "deployment" / "best_model.pkl"
    )

    model_path.parent.mkdir(
        parents=True,
        exist_ok=True
    )

    joblib.dump(best_model, model_path)

    # Log model artifact
    mlflow.log_artifact(
        str(model_path),
        artifact_path="model"
    )

    print("Model training completed successfully!")
    print("Best parameters:", grid_search.best_params_)
    print("Best CV F1-score:", grid_search.best_score_)
    print("Model saved to:", model_path)

    print("\nTest Classification Report:")
    print(
        classification_report(
            ytest,
            y_pred_test,
            zero_division=0
        )
    )
